INSERT INTO provenance.spatial_asset_inventory(
 campaign_id,external_key,asset_name,alternate_names,asset_class,authority_name,country_code,admin_level_1,locality,legal_status,stated_area_sqm,source_url,acquisition_status,geometry_status,missing_material,evidence_notes,risk_priority,risk_reason,check_status
)
SELECT c.id,a.external_key,a.asset_name,a.alternate_names,a.asset_class,a.authority_name,'NG',c.admin_level_1,a.locality,a.legal_status,a.stated_area_sqm,a.source_url,a.acquisition_status,a.geometry_status,a.missing_material,a.evidence_notes,a.risk_priority,a.risk_reason,'excluded'
FROM assets a JOIN provenance.spatial_acquisition_campaigns c ON c.external_key = a.campaign_key
ON CONFLICT(external_key) DO NOTHING;

